args.CommandLine:
"$desktop = [Environment]::GetFolderPath("Desktop")
Write-Host "Desktop: $desktop"
Write-Host "--- AppData Roaming / Local / LocalLow ---"
Get-ChildItem -Path $env:APPDATA, $env:LOCALAPPDATA, "$env:USERPROFILE\AppData\LocalLow" -Filter "*Slay*" -ErrorAction SilentlyContinue | Select-Object FullName
Get-ChildItem -Path $env:APPDATA, $env:LOCALAPPDATA, "$env:USERPROFILE\AppData\LocalLow" -Filter "*MegaCrit*" -ErrorAction SilentlyContinue | Select-Object FullName
Get-ChildItem -Path "$env:USERPROFILE\Saved Games", "$env:USERPROFILE\Documents" -Filter "*Slay*" -ErrorAction SilentlyContinue | Select-Object FullName
Write-Host "--- Steam Libraries ---"
$steamPaths = @("C:\Program Files (x86)\Steam", "C:\Program Files\Steam", "D:\Steam", "D:\SteamLibrary", "E:\SteamLibrary")
foreach ($p in $steamPaths) {
    if (Test-Path "$p\steamapps\libraryfolders.vdf") {
        Get-Content "$p\steamapps\libraryfolders.vdf" | Select-String '"path"'
    }
    if (Test-Path "$p\steamapps\common") {
        Get-ChildItem "$p\steamapps\common" -Filter "*Slay*" -ErrorAction SilentlyContinue | Select-Object FullName
    }
}
"

